import React, { FC, PropsWithChildren, Fragment, ReactChildren } from 'react';
import { isFunction } from '@arco-design/web-react/es/_util/is';
import toArray from 'rc-util/es/Children/toArray';
import { FormStepProps, IFormStep, ReactiveReactNode } from '../types';
import { VoidField } from '@formily/react';

export type SlotTypes = 'top' | 'header' | 'arcoSteps' | 'buttons' | 'residentContent' | 'footer';

export type SlotComponentTypes =
  | 'TopSlot'
  | 'HeaderSlot'
  | 'ArcoStepsSlot'
  | 'ResidentContentSlot'
  | 'FooterSlot'
  | 'ButtonSlot';

export const slotTypeToSlotComponentType = (slot: SlotTypes) => {
  const [first, ...rest] = slot;
  const slotDisplayName = [first.toUpperCase(), ...rest, 'Slot'].join('');
  return slotDisplayName as SlotComponentTypes;
};

export const createSlot = (ComponentName: string) => {
  const Component: FC<PropsWithChildren<any>> = ({ children }) => children

  Component.displayName = ComponentName;
  return Component;
};

export const TopSlot = createSlot('TopSlot');
export const HeaderSlot = createSlot('HeaderSlot');
export const ArcoStepsSlot = createSlot('ArcoStepsSlot');
export const ResidentContentSlot = createSlot('ResidentContentSlot');
export const FooterSlot = createSlot('FooterSlot');
export const ButtonsSlot = createSlot('ButtonSlot');

/**
 * 获取 FormStep 的各种插槽
 * 如 footer、buttons 内容
 * 其中，该方法是被 FormStep 组件调用的， slot 为一个函数，假如依赖 IFormStep 若干属性，这里可以响应式更新
 * @param props
 * @param slotName
 * @returns
 */
export const getSlot = (props: FormStepProps, slotName: SlotTypes, formStep: IFormStep) => {
  const slotComponentType = slotTypeToSlotComponentType(slotName);
  const childNodes = toArray(props.children, { keepEmpty: false });
  const [firstSlot] = childNodes.filter(node => {
    const [component] = node.props?.component || [];
    return component?.displayName === slotComponentType;
  });

  // 为什么要取最后 SlotName 的 children？
  // 用于 <Slot>{() => xxx}</Slot> 的场景
  const _slot = firstSlot?.props?.children;
  // 兼容 props['buttons'] & <ButtonsSlot> xxx </ButtonsSlot> 的场景
  // props 上优先
  const slot: ReactiveReactNode = props[slotName] || _slot;

  if (firstSlot && _slot) {
    return <VoidField key={firstSlot.props.name} name={firstSlot.props.name}>{isFunction(slot) ? slot?.(formStep) : slot}</VoidField>;
  } else if (firstSlot) {
    return firstSlot;
  } else {
    return undefined;
  }
};
